#include <iostream>
#include <string>
using namespace std;

class monhoc {
private:
    string mamon, tenmon;
    int sotinchi;

public:
    void nhap() {
        cout << "Ma mon: ";
        cin >> mamon;
        cin.ignore();

        cout << "Ten mon: ";
        getline(cin,tenmon);

        cout << "So tin chi: ";
        cin >> sotinchi;
        cin.ignore();
    }

    int getTinChi() {
        return sotinchi;
    }

    void xuat() {
        cout << mamon << " - " << tenmon
             << " - " << sotinchi << " tin chi\n";
    }
};

class QuanLyMonHoc : public monhoc { //khai bao quanlimonhoc ke thua tu mon hoc
private:
    string makyhoc;
    int somon;
    monhoc ds[100];

public:
    void nhapkyhoc() {
        cout << "Ma ky hoc: ";
        cin >> makyhoc;

        cout << "So mon hoc: ";
        cin >> somon;
        cin.ignore();

        for (int i = 0; i < somon; i++) {
            cout << "\nNhap mon hoc thu " << i + 1 << ":\n";
            ds[i].nhap();
        }
    }

    int tongtinchi() {
        int tong = 0;

        for (int i = 0; i < somon; i++) {
            tong += ds[i].getTinChi();
        }

        return tong;
    }

    void xuatkyhoc() {
        cout << "Ky hoc " << makyhoc
             << " co " << tongtinchi()
             << " tin chi\n";
    }
};

int main() {
    int n;
    cout << "Nhap so ky hoc: ";
    cin >> n;
    cin.ignore();

    QuanLyMonHoc ds[100];

    for (int i = 0; i < n; i++) {
        cout << "\nNHAP KY HOC THU " << i + 1 << ":\n";
        ds[i].nhapkyhoc();
    }

    int maxtinchi = ds[0].tongtinchi();

    for (int i = 1; i < n; i++) {
        if (ds[i].tongtinchi() > maxtinchi) {
            maxtinchi = ds[i].tongtinchi();
        }
    }

    cout << "\nCAC KY HOC CO SO TIN CHI CAO NHAT:\n";

    for (int i = 0; i < n; i++) {
        if (ds[i].tongtinchi() == maxtinchi) {
            ds[i].xuatkyhoc();
        }
    }

    return 0;
}

